{
"title": "Conversation Metrics Panel",
"body": "<div class="panel">
  <h2 class="title">📊 Conversation Stats</h2>

  <section class="section">
    <h3 class="subtitle">Message Counts</h3>
    <div id="role-stats" class="stats"></div>
  </section>

  <section class="section">
    <h3 class="subtitle">Latest Tool Calls (5)</h3>
    <ul id="tool-list" class="tool-list"></ul>
  </section>

  <section class="section">
    <h3 class="subtitle">Longest Message</h3>
    <div id="longest-msg" class="metric-value"></div>
  </section>

  <footer class="footer">
    <span>Updated dynamically every draw</span>
  </footer>
</div>",
"css": ".panel {
  font-family: 'SF Mono', 'Fira Code', monospace;
  background: #1a1b26;
  color: #a9b1d6;
  border-radius: 12px;
  padding: 20px;
  min-width: 280px;
  max-width: 360px;
  box-shadow: 0 4px 24px rgba(0,0,0,0.4);
  border: 1px solid #292e42;
}

.title {
  margin: 0 0 16px;
  font-size: 18px;
  color: #c0caf5;
  border-bottom: 2px solid #3b4261;
  padding-bottom: 10px;
}

.section {
  margin: 14px 0;
}

.subtitle {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  color: #565f89;
  margin: 0 0 8px;
}

.stats {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.stat-badge {
  background: #292e42;
  padding: 4px 12px;
  border-radius: 20px;
  font-size: 13px;
  color: #7aa2f7;
  border: 1px solid #3b4261;
}

.stat-badge .count {
  font-weight: bold;
  color: #9ece6a;
}

.tool-list {
  list-style: none;
  padding: 0;
  margin: 0;
}

.tool-list li {
  background: #24283b;
  margin: 4px 0;
  padding: 6px 10px;
  border-radius: 6px;
  font-size: 12px;
  color: #bb9af7;
  border-left: 3px solid #bb9af7;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.tool-list li:first-child {
  border-left-color: #7aa2f7;
  color: #7aa2f7;
}

.metric-value {
  font-size: 36px;
  font-weight: bold;
  color: #9ece6a;
  line-height: 1;
}

.longest-label {
  font-size: 12px;
  color: #565f89;
  margin-top: 4px;
}

.footer {
  margin-top: 16px;
  padding-top: 10px;
  border-top: 1px solid #292e42;
  font-size: 10px;
  color: #3b4261;
  text-align: center;
}",
"scripts": [
  "(() => {
  const msgs = ml.current.messages || [];

  // Count by role
  const roleCount = {};
  ["system","user","assistant","tool"].forEach(role => {
    roleCount[role] = msgs.filter(m => m.role === role).length;
  });

  const statsEl = root.querySelector('#role-stats');
  if (statsEl) {
    const badges = Object.entries(roleCount)
      .filter(([_, c]) => c > 0)
      .map(([role, count]) => 
        `<span class="stat-badge">${role}: <span class="count">${count}</span></span>`
      );
    statsEl.innerHTML = badges.join('') || '<span style="color:#565f89;font-size:12px;">None</span>';
  }

  // Latest 5 tool call names
  const tools = msgs
    .filter(m => m.tool_calls && m.tool_calls.length > 0)
    .flatMap(m => m.tool_calls.map(tc => tc.function.name));

  const recent5 = tools.slice(-5);
  const toolListEl = root.querySelector('#tool-list');
  if (toolListEl) {
    toolListEl.innerHTML = recent5.length > 0
      ? recent5.map(name => `<li>${name}</li>`).join('')
      : '<li style="color:#3b4261;">No tool calls yet</li>';
  }

  // Longest message content length
  const lengths = msgs.map(m => (m.content || '').length);
  const maxLen = lengths.length > 0 ? Math.max(...lengths) : 0;

  const longestEl = root.querySelector('#longest-msg');
  if (longestEl) {
    longestEl.innerHTML = `${maxLen}<div class="longest-label">characters</div>`;
  }
})();"
]
}
